    private fun writeScrollMetrics(writer: ProtocolWriter, value: ScrollMetrics) {
        writer.writeF32(value.scale)
        writer.writeF32(value.scrollX)
        writer.writeF32(value.scrollY)
        writer.writeF32(value.maxScrollX)
        writer.writeF32(value.maxScrollY)
        writeSize(writer, value.contentSize)
        writeSize(writer, value.viewportSize)
        writer.writeF32(value.textAreaX)
        writer.writeF32(value.textAreaWidth)
        writer.writeBoolI32(value.canScrollX)
        writer.writeBoolI32(value.canScrollY)
    }
