        val kind = VisualLineKind.fromValue(reader.readI32())
        val ownsGutterSemantics = reader.readBoolI32()
        val foldState = FoldState.fromValue(reader.readI32())
        val lineNumber = reader.readI32()
        val lineBackgroundColor = reader.readI32()
        val gutterBackgroundColor = reader.readI32()
        return VisualLine(logicalLine, wrapIndex, lineNumberPosition, runs, kind, ownsGutterSemantics, foldState, lineNumber, lineBackgroundColor, gutterBackgroundColor)
    }
    private fun writeVisualLine(writer: ProtocolWriter, value: VisualLine) {
        writer.writeI32(value.logicalLine)
        writer.writeI32(value.wrapIndex)
        writePointF(writer, value.lineNumberPosition)
        writeListVisualRun(writer, value.runs)
        writer.writeI32(value.kind.value)
        writer.writeBoolI32(value.ownsGutterSemantics)
        writer.writeI32(value.foldState.value)
        writer.writeI32(value.lineNumber)
        writer.writeI32(value.lineBackgroundColor)
        writer.writeI32(value.gutterBackgroundColor)
