    fun decodeVisualRun(bytes: ByteArray): VisualRun = readVisualRun(ProtocolReader(bytes))
    private fun readVisualRun(reader: ProtocolReader): VisualRun {
        val `type` = VisualRunType.fromValue(reader.readI32())
        val x = reader.readF32()
        val y = reader.readF32()
        val text = reader.readUtf8String()
        val style = readTextStyle(reader)
        val iconId = reader.readI32()
        val colorValue = reader.readI32()
        val width = reader.readF32()
        val padding = reader.readF32()
        val margin = reader.readF32()
        val active = reader.readBoolI32()
        return VisualRun(`type`, x, y, text, style, iconId, colorValue, width, padding, margin, active)
    }
    private fun writeVisualRun(writer: ProtocolWriter, value: VisualRun) {
        writer.writeI32(value.`type`.value)
        writer.writeF32(value.x)
        writer.writeF32(value.y)
        writer.writeUtf8String(value.text)
        writeTextStyle(writer, value.style)
        writer.writeI32(value.iconId)
        writer.writeI32(value.colorValue)
        writer.writeF32(value.width)
        writer.writeF32(value.padding)
        writer.writeF32(value.margin)
        writer.writeBoolI32(value.active)
    }
